struct Wrap { value: Item }
mut seed := [] mut j := 0 while j < 2 { seed = push(seed, [0]) j += 1 }
mut state := seed seed = null

export func snapshot() { return state }

func observe(n) { assert_equal(state[0][0], n - 1) return n }
export func edit(n, payload) { state[0] = payload  return n }

